"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51059"],{83957(e){e.exports=JSON.parse('{"id":"FIN-277","slug":"broker","term":"Broker","also_known_as":[],"difficulty":"Intermediate","definition":"A broker is a person or firm that arranges transactions between buyers and sellers in return for a fee or commission, without usually owning the asset being traded.","explanation":["In financial markets, a broker acts as an agent. When you ask a broker to buy shares, they find a seller and execute the trade on your behalf at the best available price. They earn a commission or fee for this service.","Brokers exist in many markets. Stockbrokers handle shares and other securities. Insurance brokers help clients find suitable insurance policies. Mortgage brokers help borrowers find home loans. Real estate brokers help buy and sell property.","The key point is that a broker works for the client and does not take the other side of the trade. This differs from a dealer, who buys and sells from their own inventory and profits from the difference between buying and selling prices. Many firms act as both, which is why they are often called broker-dealers.","Brokers are usually regulated and may have a duty to act in their clients\' best interests, depending on the jurisdiction and the service provided. Understanding how a broker is paid helps clients spot possible conflicts of interest."],"note":"","total":1500,"prev":{"slug":"bridge-loan","term":"Bridge Loan"},"next":{"slug":"brokerage","term":"Brokerage"}}')}}]);